        if self.spy in data.Bars and self.spy_sma.IsReady:
            current_spy_close = data.Bars[self.spy].Close
            current_spy_sma = self.spy_sma.Current.Value

            if self.previous_spy_close is not None:
                self.current_spy_buy_signal = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and current_spy_close > current_spy_sma
                )
                self.current_spy_sell_signal = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and current_spy_close < current_spy_sma
                )
            else:
                self.current_spy_buy_signal = False
                self.current_spy_sell_signal = False

            self.previous_spy_close = current_spy_close
            self.previous_spy_sma = current_spy_sma

        if self.aapl in data.Bars:
            current_aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if current_aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = current_aapl_close

        if self.IsWarmingUp:
            return

        if len(available_symbols) != len(self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.strategy_a_lot > 0 and self.current_spy_sell_signal:
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="Strategy A Sell"
            )

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > self.RSI_THRESHOLD:
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="Strategy B Sell"
            )

        if self.strategy_a_lot == 0 and self.current_spy_buy_signal:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A Buy"
                )

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B Buy"
                    )

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            return

        quantity = orderEvent.FillQuantity
        tag = orderEvent.Tag

        if tag == "Strategy A Buy":
            self.strategy_a_lot += quantity
        elif tag == "Strategy A Sell":
            self.strategy_a_lot = max(0, self.strategy_a_lot + quantity)
        elif tag == "Strategy B Buy":
            self.strategy_b_lot += quantity
        elif tag == "Strategy B Sell":
            self.strategy_b_lot = max(0, self.strategy_b_lot + quantity)
