        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.SetWarmUp(100, Resolution.Daily)

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0
        self.previous_aapl_close = None

        self.lots = {
            self.spy: 0,
            self.aapl: 0
        }

        self.pending_orders = {}
        self.order_details = {}

        self.rsi_threshold = 70

    def OnData(self, data):
        if self.spy in data.Bars:
            spy_close = data.Bars[self.spy].Close

            previous_close = self.previous_spy_close
            previous_sma = self.previous_spy_sma

            self.spy_sma.Update(self.Time, spy_close)
            current_sma = self.spy_sma.Current.Value

            self.previous_spy_close = spy_close
            self.previous_spy_sma = current_sma

            spy_crossed_above = (
                previous_close is not None and
                previous_sma is not None and
                self.spy_sma.IsReady and
                previous_close <= previous_sma and
                spy_close > current_sma
            )

            spy_crossed_below = (
                previous_close is not None and
                previous_sma is not None and
                self.spy_sma.IsReady and
                previous_close >= previous_sma and
                spy_close < current_sma
            )
        else:
            spy_crossed_above = False
            spy_crossed_below = False

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(self.Time, aapl_close)

        required_symbols = {self.spy, self.aapl, self.ibm, self.bac, self.aig}
        if not required_symbols.issubset(set(data.Bars.Keys)):
            return

        if self.IsWarmingUp:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.lots[self.spy] > 0 and self.pending_orders.get(self.spy) is None:
            if spy_crossed_below:
                self._submit_sell(self.spy, self.lots[self.spy], "Strategy A liquidation")

        if self.lots[self.aapl] > 0 and self.pending_orders.get(self.aapl) is None:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > self.rsi_threshold:
                self._submit_sell(self.aapl, self.lots[self.aapl], "Strategy B liquidation")

        if self.lots[self.spy] == 0 and self.pending_orders.get(self.spy) is None:
            if spy_crossed_above:
                quantity = int(math.floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / float(spy_close)
                ))
                if quantity > 0:
                    self._submit_buy(self.spy, quantity, "Strategy A buy")

        if self.lots[self.aapl] == 0 and self.pending_orders.get(self.aapl) is None:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000:
                quantity = int(math.floor(20000 / float(aapl_close)))
                if quantity > 0:
                    self._submit_buy(self.aapl, quantity, "Strategy B buy")

    def _submit_buy(self, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)
        self.pending_orders[symbol] = ticket.OrderId
        self.order_details[ticket.OrderId] = {
            "symbol": symbol,
            "side": "buy"
        }

    def _submit_sell(self, symbol, quantity, tag):
        if quantity <= 0:
            return

        ticket = self.MarketOrder(symbol, -quantity, tag=tag)
        self.pending_orders[symbol] = ticket.OrderId
        self.order_details[ticket.OrderId] = {
            "symbol": symbol,
            "side": "sell"
        }

    def OnOrderEvent(self, order_event):
        order_id = order_event.OrderId

        if order_id not in self.order_details:
            return

        details = self.order_details[order_id]
        symbol = details["symbol"]

        if order_event.Status == OrderStatus.Filled:
            fill_quantity = int(order_event.FillQuantity)

            if details["side"] == "buy":
                self.lots[symbol] += fill_quantity
            else:
                self.lots[symbol] -= abs(fill_quantity)
                self.lots[symbol] = max(0, self.lots[symbol])

            if self.pending_orders.get(symbol) == order_id:
                self.pending_orders[symbol] = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.CancelPending
        ):
            if self.pending_orders.get(symbol) == order_id:
                self.pending_orders[symbol] = None
